from pathlib import Path
import subprocess,json,hashlib
w=Path(__file__).resolve().parent
cc=w/"toolchains/w64devkit/bin/gcc.exe"
d=w/"nova31-rf-tests";d.mkdir(exist_ok=True)
def compile_test(name, version, source, extra=()):
    p = w / version / 'nyx/nyx_gui'
    lib = p / 'libs/btstack'
    c = d / (name + '.c')
    exe = d / (name + '.exe')
    c.write_text(source)
    sources = [p / 'bluetooth/nova_bt_protocol.c', p / 'bluetooth/nova_bt_trace.c', *lib.rglob('*.c')]
    args = [str(cc), '-std=gnu11', '-O1', '-Wall', '-Wextra', '-ffunction-sections', '-fdata-sections', '-Wl,--gc-sections', *extra, '-I' + str(p / 'bluetooth'), '-I' + str(lib), str(c), *map(str, sources), '-o', str(exe)]
    r = subprocess.run(args, capture_output=True, text=True)
    assert r.returncode == 0, r.stderr[-8000:]
    return exe
test='\n#include <assert.h>\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include "nova_bt.h"\n#undef assert\n#define assert(x) do {if(!(x)){fprintf(stderr,"assertion line %d: %s\\n",__LINE__,#x);exit(1);}}while(0)\nstatic unsigned now,us,clock_reads,in_at,in_n,packet_cost;\nstatic uint8_t in[16];\nuint32_t nova_bt_now(void){return now;}\nuint32_t nova_bt_now_us(void){clock_reads++;return ++us;}\nint nova_bt_radio_open(void){return 1;}\nvoid nova_bt_radio_close(void){}\nint nova_bt_radio_read(void){return in_at<in_n?in[in_at++]:-1;}\nint nova_bt_radio_write(uint8_t value){(void)value;return 1;}\n#include "nova_bt_stack.c"\n#ifdef AUDIT_OLD\nstatic uint32_t nova_bt_take_buttons(unsigned side){return side<2?status.pad[side].buttons:0;}\n#endif\nstatic void decode(unsigned side,unsigned buttons,unsigned at)\n{\n    uint8_t r[14]={0x30};r[3]=buttons;r[4]=buttons>>8;r[5]=buttons>>16;\n    r[6]=r[9]=0x45;r[7]=r[10]=0x38;r[8]=r[11]=0x67;\n    now=at;assert(nova_bt_decode(&status.pad[side],side,r,sizeof r,now));\n}\nstatic void delayed_callback(void *unused){(void)unused;us+=3000;}\nstatic void delayed_packet(uint8_t type,uint8_t *p,uint16_t n)\n{(void)type;(void)p;(void)n;us+=packet_cost;}\n\nstatic void reply(unsigned kind,int value,unsigned size,unsigned err,unsigned handle){\n rf_pending.active=1;rf_pending.side=0;rf_pending.kind=kind;rf_pending.handle=0x42;rf_pending.generation=link[0].generation;\n rf_pending.opcode=kind==4?0x1401:kind==1?0x1403:kind==0?0x1405:0x0c2d;\n uint8_t p[10]={14,8,1,rf_pending.opcode,rf_pending.opcode>>8,err,handle,handle>>8,value,value>>8};rf_reply(p,size);\n}\nint main(void){\n nova_bt_peer pair[2]={0};pair[0].valid=1;pair[0].mac[0]=0x40;pair[0].host[0]=0x60;memset(pair[0].key,0x70,16);\n assert(nova_bt_start(pair));status.state=NOVA_BT_OFF;\n link[0].handle=0x42;link[0].generation=1;status.pad[0].hid_open=1;\n reply(0,-32,9,0,0x42);reply(0,0,9,0,0x42);reply(0,5,9,0,0x42);\n nova_bt_rf *rf=&status.pad[0].rf;assert(rf->samples[0]==3&&rf->value[0]==5&&rf->minimum[0]==-32&&rf->maximum[0]==5);\n reply(1,255,9,0,0x42);reply(2,-6,9,0,0x42);reply(3,10,9,0,0x42);reply(4,65535,10,0,0x42);\n assert(rf->value[1]==255&&rf->value[2]==-6&&rf->value[3]==10&&rf->value[4]==65535);\n reply(2,127,9,0,0x42);assert(rf->error[2]==0xfd&&rf->samples[2]==1);\n reply(0,1,8,0,0x42);assert(rf->error[0]==0xff&&status.rf_bad_replies==1);\n reply(0,1,9,0,0x43);assert(rf->error[0]==0xff&&status.rf_bad_replies==2&&rf->samples[0]==3);\n reply(1,0,6,1,0);assert((link[0].rf_disabled&2)&&rf->error[1]==1);\n reply(4,0,6,0x11,0);assert((link[0].rf_disabled&16)&&rf->error[4]==0x11);\n rf_pending.active=1;rf_pending.side=0;rf_pending.kind=0;rf_pending.generation=1;rf_pending.sent=now;now+=1501;rf_run();\n assert(!rf_pending.active&&rf->error[0]==0xfe&&(link[0].rf_disabled&1)&&!failure);\n rf_pending.active=1;rf_pending.generation=0;rf_pending.kind=3;rf_pending.sent=now;now+=1501;rf_run();assert(!rf_pending.active&&rf->error[3]==0);\n // Old generation cannot publish a late reply into a reconnected pad.\n rf_pending.active=1;rf_pending.side=0;rf_pending.kind=0;rf_pending.handle=0x42;rf_pending.generation=0;rf_pending.opcode=0x1405;\n uint8_t late[]={14,7,1,5,20,0,0x42,0,99};rf_reply(late,9);assert(!rf_pending.active&&rf->samples[0]==3);\n // A 0x21 ACK does not distort full-report gaps. Wrapping clock remains valid.\n memset(&status.pad[0],0,sizeof status.pad[0]);decode(0,0,0xfffffff0u);decode(0,0,20);decode(0,0,320);\n assert(status.pad[0].full_reports==3&&status.pad[0].max_full_gap_ms==300&&status.pad[0].full_gaps_50ms==1&&status.pad[0].full_gaps_250ms==1);\n // Draw callback is throttled to 2 ms and never dispatches LVGL or recurses.\n status.draw_yields=0;us=100;draw_seen=0;nova_bt_draw_poll();assert(status.draw_yields==1);nova_bt_draw_poll();assert(status.draw_yields==1);\n us+=2000;nova_bt_draw_poll();assert(status.draw_yields==2);draw_busy=1;us+=2000;nova_bt_draw_poll();assert(status.draw_yields==2);draw_busy=0;\n nova_bt_stop();us+=2000;nova_bt_draw_poll();assert(status.draw_yields==2);\n puts("PASS RF: signed/zero RSSI, vendor quality, TX range, unsigned counter, bounds/handle/generation, unsupported/timeout isolation; full-report gaps/wrap; bounded draw polling");\n}\n'
exe=compile_test("rf", "hekate-nova-pro-v31", test)
r=subprocess.run([str(exe)],capture_output=True,text=True,timeout=20)
print(r.stdout,r.stderr);assert r.returncode==0,r.returncode
p=w/"hekate-nova-pro-v31/nyx/nyx_gui/bluetooth"
(w/"nova31-rf-check.json").write_text(json.dumps({"passed":True,"physical_validation":False,"output":r.stdout,"source_sha256":{n:hashlib.sha256((p/n).read_bytes()).hexdigest()for n in ["nova_bt.h","nova_bt_protocol.c","nova_bt_stack.c"]}},indent=2))
